std::string longestPalindromicSubstring(std::string s) {
  int n = s.size();
  if (n == 0) return "";
  int start = 0, maxLength = 1;

  for (int i = 0; i < n; ++i) {
    int l = i, r = i;

    while (r < n - 1 && s[r] == s[r + 1])
      r++;
    i = r;

