public class Solution {
    public int myAtoi(String str) {
        long result = 0;
        int i = 0, sign = 1;
        while (i < str.length() && str.charAt(i) == ' ') i++;
        if (i < str.length() && (str.charAt(i) == '-' || str.charAt(i) == '+')) sign = (str.charAt(i++) == '+') ? 1 : -1;
        while (i < str.length() && Character.isDigit(str.charAt(i))) {
