public class NQueens {
    public static List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(board[i], '.');
        }
        solve(result, board, n, 0);
        return result;
    }

    private static boolean isSafe(char[][] board, int row, int col) {
        // Check column
        for (int i = 0; i < row; i++) {
            if (board[i][col] == 'Q') return false;
        }
        // Check upper left diagonal
        for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) {
            if (board[i][j] == 'Q') return false;
        }
        // Check upper right diagonal
        for (int i = row, j = col; i >= 0 && j < board.length; i--, j++) {
            if (board[i][j] == 'Q') return false;
        }
        return true;
    }

    private static void solve(List<List<String>> result, char[][] board, int n, int col) {
        if (col == n) {
            List<String> temp = new ArrayList<>();
            for (char[] row : board) {
                temp.add(new String(row));
            }
            result.add(temp);
            return;
        }
        for (int i = 0; i < n; i++) {
            if (isSafe(board, i, col)) {
                board[i][col] = 'Q';
                solve(result, board, n, col + 1);
                board[i][col] = '.';
            }
        }
    }

    public static void main(String[] args) {
        int n = 4;
        List<List<String>> result = solveNQueens(n);
        System.out.println(result);
    }
}

public class Solution {
    public static int totalNQueens(int n) {
        int[] cols = new int[n];
        return backtrack(n, cols, 0);
    }

    private static int backtrack(int n, int[] cols, int row) {
        if (row == n) {
            return 1;
        }

        int count = 0;
        for (int col = 0; col < n; col++) {
            if (isSafe(cols, row, col)) {
                cols[row] = col;
                count += backtrack(n, cols, row + 1);
            }
        }

        return count;
    }

    private static boolean isSafe(int[] cols, int row, int col) {
        for (int i = 0; i < row; i++) {
            if (cols[i] == col || Math.abs(i - row) == Math.abs(cols[i] - col)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int n = 4;
        System.out.println(totalNQueens(n)); // Output: 2
    }
}

