    while (!q.empty()) {
        int size = q.size();
        std::unordered_set<std::string> currentLevel;

        for (int i = 0; i < size; ++i) {
            std::string currentWord = q.front();
            q.pop();

            if (currentWord == endWord) {
                return steps;
            }

            for (int j = 0; j < currentWord.length(); ++j) {
