        for (size_t j = 0; j < std::min(word1.size(), word2.size()); ++j) {
            if (word1[j] != word2[j]) {
                if (graph[word1[j]].find(word2[j]) == graph[word1[j]].end()) {
                    graph[word1[j]].insert(word2[j]);
                    in_degree[word2[j]]++;
                }
                found = true;
                break;
            }
        }

        if (!found && word1.size() > word2.size()) {
            return "";
        }
    }

    std::queue<char> q;
    for (const auto& pair : in_degree) {
        if (pair.second == 0) {
            q.push(pair.first);
        }
    }

    std::string result;
    while (!q.empty()) {
