        result += c;

        for (char neigh : graph[c]) {
            in_degree[neigh]--;
            if (in_degree[neigh] == 0) {
                q.push(neigh);
            }
        }
    }

    if (result.size() < in_degree.size()) {
        return "";
    }

    return result;
}

