    }

    private void mergeSort(Integer[] indices, int[] nums, int[] result, int left, int right) {
        if (left >= right) {
            return;
        }

        int mid = (left + right) / 2;
        mergeSort(indices, nums, result, left, mid);
        mergeSort(indices, nums, result, mid + 1, right);

        merge(indices, nums, result, left, mid, right);
    }

    private void merge(Integer[] indices, int[] nums, int[] result, int left, int mid, int right) {
        int[] temp = new int[right - left + 1];
        int k = 0;

        int i = left;
        int j = mid + 1;
        int count = 0;

        while (i <= mid && j <= right) {
            if (nums[indices[i]] <= nums[indices[j]]) {
                result[indices[i]] += count;
                temp[k++] = indices[i++];
            } else {
                count++;
                temp[k++] = indices[j++];
            }
        }

        while (i <= mid) {
            result[indices[i]] += count;
            temp[k++] = indices[i++];
        }

        while (j <= right) {
            temp[k++] = indices[j++];
        }

        System.arraycopy(temp, 0, indices, left, temp.length);
    }
