            }
        }

        memo[i][j] = maxLen + 1;
        return memo[i][j];
    }

    private boolean isValid(int[][] matrix, int i, int j) {
        return i >= 0 && i < matrix.length && j >= 0 && j < matrix[0].length;
    }
}

