    while max_heap:
        temp = []
        for _ in range(min(k, len(max_heap))):
            freq, char = heapq.heappop(max_heap)
            result.append(char)
            if freq + 1 < 0:
                temp.append((freq + 1, char))

        if not max_heap and len(result) < len(s):
            return ""

        for entry in temp:
            heapq.heappush(max_heap, entry)

    return ''.join(result)

