public class Solution {
    public int longestSubstring(String s, int k) {
        if (s == null || k <= 0) return 0;

        Map<Character, Integer> charCount = new HashMap<>();
        for (char ch : s.toCharArray())
            charCount.put(ch, charCount.getOrDefault(ch, 0) + 1);

        for (Map.Entry<Character, Integer> entry : charCount.entrySet()) {
            if (entry.getValue() < k) {
                String[] substrings = s.split(String.valueOf(entry.getKey()));
                int maxLen = 0;
                for (String substring : substrings) {
                    maxLen = Math.max(maxLen, longestSubstring(substring, k));
                }
                return maxLen;
            }
        }
        return s.length();
    }

    private String[] split(String s, char delimiter) {
        List<String> substrings = new ArrayList<>();
        int start = 0;
        int end = s.indexOf(delimiter);
        while (end != -1) {
            substrings.add(s.substring(start, end));
            start = end + 1;
            end = s.indexOf(delimiter, start);
        }
        substrings.add(s.substring(start));
        return substrings.toArray(new String[0]);
    }
}

