public class Solution {
    public int numberOfArithmeticSlices(int[] A) {
        int n = A.length;
        int count = 0, cur = 0;
        for (int i = 2; i < n; i++) {
            if (A[i] - A[i - 1] == A[i - 1] - A[i - 2]) {
                cur++;
                count += cur;
            } else {
                cur = 0;
            }
        }
        return count;
    }
}

