    def search_squares(self, index, length, square, prefix_map, squares):
        if index == length:
            squares.append(square.copy())
            return
        prefix = self.build_prefix(square, index)
        for word in prefix_map.get(prefix, []):
            square.append(word)
            self.search_squares(index + 1, length, square, prefix_map, squares)
            square.pop()

    def build_prefix_map(self, words):
        prefix_map = {}
        for word in words:
            for i in range(len(word)):
