import java.util.*;

public class Solution {
    public int minMutation(String start, String end, List<String> bank) {
        Queue<String> q = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        q.offer(start);
        visited.add(start);
        int depth = 0;

        while (!q.isEmpty()) {
            int levelSize = q.size();
            for (int i = 0; i < levelSize; i++) {
                String current = q.poll();
                if (current.equals(end)) {
                    return depth;
                }

                for (String gene : bank) {
                    if (!visited.contains(gene) && isOneMutationApart(current, gene)) {
                        q.offer(gene);
                        visited.add(gene);
                    }
                }
            }
            depth++;
        }
        return -1;
    }

    private boolean isOneMutationApart(String s1, String s2) {
        int diffCount = 0;
        for (int i = 0; i < s1.length(); i++) {
            if (s1.charAt(i) != s2.charAt(i)) {
                diffCount++;
            }
        }
        return diffCount == 1;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        List<String> bank = Arrays.asList("AACCGGTA");
        System.out.println(solution.minMutation("AACCGGTT", "AACCGGTA", bank)); // Output: 1
    }
}

