import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static int findMinStep(String board, String hand) {
        Map<Character, Integer> handCount = new HashMap<>();
        for (char c : hand.toCharArray()) {
            handCount.put(c, handCount.getOrDefault(c, 0) + 1);
        }

        Map<String, Integer> memo = new HashMap<>();
        return findMinStepHelper(board, memo, handCount);
    }

    private static int findMinStepHelper(String board, Map<String, Integer> memo, Map<Character, Integer> handCount) {
        if (board.isEmpty()) {
            return 0;
        }
        if (memo.containsKey(board)) {
            return memo.get(board);
        }

        int result = Integer.MAX_VALUE;
        int i = 0;
        while (i < board.length()) {
            int j = i;
            while (j < board.length() && board.charAt(i) == board.charAt(j)) {
                j++;
            }

            char color = board.charAt(i);
            int required = 3 - (j - i);
            if (handCount.containsKey(color) && handCount.get(color) >= required) {
                handCount.put(color, handCount.get(color) - required);
                String nextBoard = board.substring(0, i) + board.substring(j);
                int tmp = findMinStepHelper(nextBoard, memo, handCount);
                if (tmp != -1) {
                    result = Math.min(result, tmp + required);
                }
                handCount.put(color, handCount.get(color) + required);
            }
            i = j;
        }

        memo.put(board, result == Integer.MAX_VALUE ? -1 : result);
        return memo.get(board);
    }

    public static void main(String[] args) {
        System.out.println(findMinStep("WRRBBW", "RB")); // Output: -1
    }
}

