std::vector<std::string> findRelativeRanks(std::vector<int>& nums) {
    std::vector<std::pair<int, int>> rank;
    for (int i = 0; i < nums.size(); ++i) {
        rank.push_back({nums[i], i});
    }
    std::sort(rank.begin(), rank.end(), [](const auto& a, const auto& b) { return a.first > b.first; });
    std::vector<std::string> result(nums.size());
    for (int i = 0; i < rank.size(); ++i) {
        if (i == 0) {
            result[rank[i].second] = "Gold Medal";
        } else if (i == 1) {
            result[rank[i].second] = "Silver Medal";
        } else if (i == 2) {
            result[rank[i].second] = "Bronze Medal";
        } else {
            result[rank[i].second] = std::to_string(i + 1);
        }
    }
    return result;
}

